/* @lc app=leetcode id=3405 lang=kotlin */ class Solution { fun fa(x: Int): Long = (1..x).fold(1L) { a, b -> a * b % 1_000_000_007L } fun iv(x: Long): Long = java.math.BigInteger.valueOf(x).modInverse(java.math.BigInteger.valueOf(1_000_000_007L)).toLong() fun countGoodArrays(n: Int, m: Int, k: Int): Int = 1_000_000_007L.let { M -> (fa(n - 1) * iv(fa(k)) % M * iv(fa(n - 1 - k)) % M * m % M * java.math.BigInteger.valueOf((m - 1).toLong()).modPow(java.math.BigInteger.valueOf((n - 1 - k).toLong()), java.math.BigInteger.valueOf(M)).toLong() % M).toInt() } }